uni.showLoading({ title: '加载中', mask: true })
let failed = false
let blocked = false
try {
  const url = await fetchOwnerDecisionVoteUrl()
  const opened = await navigateToExternalUrl(withVoteParams(url))
  if (!opened) blocked = true
  return opened
} catch (e) {
  console.error('业主决策投票地址', e)
  failed = true
  return false
} finally {
  uni.hideLoading()
  // 接口异常时必须清理 URL 携带的决策 ID，否则后续启动/回跳会反复尝试进入业主决策页
